				&QueryString;

declare @name nvarchar(4000)
select @name = rtrim(isnull(case when @@language = 'V' then ten_tk else ten_tk2 end, '')) from dmtk where tk = @acct
select 'this._itemName = ''' + replace(replace(@name, '\', '\\'), '''', '\''') + ''';this._queryFilterString = ''' + replace(replace(@@queryString, '\', '\\'), '''', '\''') + ''';init$GridQuery$(this);' as message
return




		&XMLWhenReportLoading;
		&XMLWhenReportClosing;





			&DeclareCommandFilter;



				&QueryString;

declare @queryWhereClause nvarchar(4000), @queryFormClause nvarchar(4000)
select @queryFormClause = 'left join dmkh b on a.ma_kh = b.ma_kh left join dmvv z on a.ma_vv = z.ma_vv'
select @queryWhereClause = 'a.tk_du = ''' +  replace(@refAcct, '''', '''''') + ''''

if isnull(@acct, '') <> '' begin
	declare @accountKey nvarchar(4000)
	select top 0 tk into #$tk from dmtk0
	exec dbo.FastBusiness$App$GetAccountKey 'a.tk', 'like', @acct, '#$tk', @@userID, @@admin, @accountKey output
	select @queryWhereClause = @queryWhereClause + ' and ' + @accountKey
end

if @ps_no_nt + @ps_no <> 0 and @ps_co_nt + @ps_co = 0 select @queryWhereClause = @queryWhereClause + ' and a.ps_no_nt + a.ps_no <> 0'
if @ps_no_nt + @ps_no = 0 and @ps_co_nt + @ps_co <> 0 select @queryWhereClause = @queryWhereClause + ' and a.ps_co_nt + a.ps_co <> 0'

if @customer <> '' set @queryWhereClause = @queryWhereClause + ' and ' + dbo.FastBusiness$Function$System$GetCodeFilter('a.ma_kh', 'inlist', @customer)
if @department <> '' set @queryWhereClause = @queryWhereClause + ' and ' + dbo.FastBusiness$Function$System$GetCodeFilter('a.ma_bp', 'inlist', @department)
if @expense <> '' set @queryWhereClause = @queryWhereClause + ' and ' + dbo.FastBusiness$Function$System$GetCodeFilter('a.ma_phi', 'inlist', @expense)
if @nh_vv1 <> '' SET @queryWhereClause = @queryWhereClause + CASE WHEN @queryWhereClause = '' THEN '' ELSE ' and ' END + 'z.nh_vv1 like ''' + REPLACE(RTRIM(@nh_vv1), '''', '''''') + '%'''
&FilterInitialize;&FilterQuery;
exec FastBusiness$Report$GLDetail @@refresh, @@pageIndex, @@pageCount, @@lastPage, @@lastCount, @@firstItem, @@lastItem,
	@@textExternal, @queryFormClause, @queryWhereClause, @dFrom, @dTo, @unit, @@admin, @@userID, @@aggregation







			&JavascriptReportInit;
			/* <flatten type="Javascript"> */
function init$GridQuery$(g) {
	var a = g._queryFilterString.split(String.fromCharCode(253));
	g._alterTitle = [null, [['%c', a[1], true], ['%s', g._itemName, true], ['%d1', formatDateView(a[2]), true], ['%d2', formatDateView(a[3]), true]]];
	var x = a[12];
	g._hiddenFields = [{Fields: 'ps_no_nt, ps_co_nt', Value: (x == '10')}];
}
/* </flatten> */



